type voidFunc = () => void

export const editorShortcutListener = ({ save, cancel }: { save: voidFunc, cancel: voidFunc }) => {
    return (e: React.KeyboardEvent<any>) => {
        if (e.key === 'Escape') {
            e.preventDefault();
            cancel();
        } else if ((e.key === 's' || e.key === 'Enter') && (e.ctrlKey || e.metaKey)) {
            e.preventDefault();
            save();
        }
    };
}